package io.argos.servertest.security.matrix;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import tools.jackson.databind.JsonNode;

/**
 * Builds a syntactically plausible request for an operation from the document alone: path
 * parameters and required query parameters from their examples, or generated by type (a random
 * UUIDv4 for {@code format: uuid}, an integer, a date-time, ...), and a minimal body from the
 * schema, or an empty JSON object when the operation declares none. The requests need not succeed;
 * they must only get past parsing often enough to reach the handler, and random identifiers name
 * nothing, so an unsafe request does not touch existing objects.
 */
public final class RequestFactory {

  /** Nesting depth of generated bodies. */
  private static final int MAX_DEPTH = 6;

  private final OpenApiSpec spec;

  public RequestFactory(OpenApiSpec spec) {
    this.spec = spec;
  }

  /**
   * One request.
   *
   * @param method upper-case HTTP method
   * @param path path with query, ready to send
   * @param body the JSON body (a {@code Map}, list or value), or null for none
   */
  public record Request(String method, String path, Object body) {}

  /** The request of {@code operation}. */
  public Request request(OpenApiSpec.Operation operation) {
    return new Request(operation.method(), path(operation), body(operation));
  }

  /** The path with path parameters filled in and required query parameters appended. */
  String path(OpenApiSpec.Operation operation) {
    String path = operation.path();
    List<String> query = new ArrayList<>();
    List<JsonNode> parameters = new ArrayList<>();
    operation.pathParameters().forEach(parameters::add);
    operation.node().path("parameters").forEach(parameters::add);
    for (JsonNode parameter : parameters) {
      String name = parameter.path("name").asString("");
      String in = parameter.path("in").asString("");
      if (in.equals("path")) {
        path = path.replace("{" + name + "}", encode(parameterValue(parameter)));
      } else if (in.equals("query") && parameter.path("required").asBoolean(false)) {
        query.add(encode(name) + "=" + encode(parameterValue(parameter)));
      }
    }
    // A path parameter the document did not declare is still a UUID-shaped placeholder.
    path = path.replaceAll("\\{[^}]+}", UUID.randomUUID().toString());
    return query.isEmpty() ? path : path + "?" + String.join("&", query);
  }

  /** The minimal body; an empty object when no schema is declared, none for GET and DELETE. */
  Object body(OpenApiSpec.Operation operation) {
    JsonNode content = operation.node().path("requestBody").path("content");
    JsonNode schema = content.path("application/json").path("schema");
    if (!schema.isMissingNode()) {
      return minimal(schema, 0);
    }
    return switch (operation.method()) {
      case "POST", "PUT", "PATCH" -> new LinkedHashMap<String, Object>();
      default -> null;
    };
  }

  private String parameterValue(JsonNode parameter) {
    if (parameter.path("example").isValueNode()) {
      return parameter.path("example").asString();
    }
    JsonNode schema = parameter.path("schema");
    if (schema.path("example").isValueNode()) {
      return schema.path("example").asString();
    }
    return String.valueOf(minimal(schema, 0));
  }

  /** The smallest value that the schema accepts, as far as generating one can tell. */
  private Object minimal(JsonNode schemaOrReference, int depth) {
    JsonNode schema = spec.resolve(schemaOrReference);
    if (schema.has("example") && !schema.path("example").isNull()) {
      return plain(schema.path("example"));
    }
    if (schema.path("enum").isArray() && !schema.path("enum").isEmpty()) {
      return plain(schema.path("enum").get(0));
    }
    String type = schema.path("type").asString(schema.has("properties") ? "object" : "string");
    return switch (type) {
      case "integer", "number" -> number(schema);
      case "boolean" -> false;
      case "array" -> array(schema, depth);
      case "object" -> object(schema, depth);
      default -> string(schema);
    };
  }

  private static Object number(JsonNode schema) {
    JsonNode minimum = schema.path("minimum");
    if (minimum.isNumber()) {
      return minimum.numberValue();
    }
    return 1;
  }

  private List<Object> array(JsonNode schema, int depth) {
    List<Object> items = new ArrayList<>();
    int count = Math.min(schema.path("minItems").asInt(0), 16);
    for (int i = 0; i < count && depth < MAX_DEPTH; i++) {
      items.add(minimal(schema.path("items"), depth + 1));
    }
    return items;
  }

  private Map<String, Object> object(JsonNode schema, int depth) {
    Map<String, Object> object = new LinkedHashMap<>();
    if (depth < MAX_DEPTH) {
      for (JsonNode name : schema.path("required")) {
        object.put(
            name.asString(), minimal(schema.path("properties").path(name.asString()), depth + 1));
      }
    }
    return object;
  }

  private static String string(JsonNode schema) {
    return switch (schema.path("format").asString("")) {
      case "uuid" -> UUID.randomUUID().toString();
      case "date-time" -> "2026-01-01T00:00:00Z";
      case "date" -> "2026-01-01";
      case "email" -> "user@example.invalid";
      default -> "x".repeat(Math.max(1, Math.min(schema.path("minLength").asInt(1), 1024)));
    };
  }

  private static Object plain(JsonNode value) {
    if (value.isNumber()) {
      return value.numberValue();
    }
    if (value.isBoolean()) {
      return value.asBoolean();
    }
    return value.asString();
  }

  private static String encode(String value) {
    return URLEncoder.encode(value, StandardCharsets.UTF_8);
  }
}
